import { byCodeUnits } from "./order";
import { type ClassDef, RustFields } from "./rust-fields";
import { rustModuleName, rustString, rustVariantName } from "./rust-names";
import { type TypeDef, tagValue } from "./type-model";

type EnumDef = Extract<TypeDef, { kind: "enum" }>;
type UnionDef = Extract<TypeDef, { kind: "union" }>;

export const RUST_GENERATED_HEADER =
	"// GENERATED by packages/bridge/scripts/gen-contract.ts from the zod schemas in\n" +
	"// packages/bridge/src/contract. Do not edit; change the schema and regenerate.\n";

const INDENT = "    ";
const RECORD_DERIVES = [
	"#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]",
	'#[cfg_attr(feature = "uniffi", derive(uniffi::Record))]',
];
const UNION_DERIVES = [
	"#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]",
	'#[cfg_attr(feature = "uniffi", derive(uniffi::Enum))]',
];
const ENUM_DERIVES = [
	"#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]",
	'#[cfg_attr(feature = "uniffi", derive(uniffi::Enum))]',
];

/** The module holding the shared numbers (`constants.ts`), beside the contract's own modules. */
const CONSTANTS_MODULE = "constants";

/**
 * The contract as Rust: one file per contract module, the shared numbers, and a `mod.rs` re-exporting
 * them all, keyed by file name. Written in rustfmt's own layout, so `cargo fmt --check` passes on it as
 * generated. `JsonValue` is written by hand in the crate (`json_value.rs`) and only referred to.
 */
export function rustModels(types: Map<string, TypeDef>, constants: [string, number][]): Map<string, string> {
	const fields = new RustFields(types);
	const byModule = new Map<string, TypeDef[]>();
	for (const type of types.values()) {
		if (type.kind === "json") continue;
		const module = rustModuleName(type.module);
		if (module === CONSTANTS_MODULE) throw new Error(`the module ${type.module} is a taken name`);
		byModule.set(module, [...(byModule.get(module) ?? []), type]);
	}
	const modules = [...byModule.keys()].sort(byCodeUnits);
	const files = new Map<string, string>();
	files.set("mod.rs", modFile([...modules, CONSTANTS_MODULE].sort(byCodeUnits)));
	files.set(`${CONSTANTS_MODULE}.rs`, constantsFile(constants));
	for (const module of modules) {
		const moduleTypes = (byModule.get(module) ?? []).sort((a, b) => byCodeUnits(a.name, b.name));
		files.set(`${module}.rs`, moduleFile(moduleTypes, fields));
	}
	return files;
}

/** Every bound is a count of characters, items, bytes or values, or milliseconds, none of them negative. */
function constantsFile(constants: [string, number][]): string {
	const declarations = constants.map(([name, value]) => {
		if (!/^[A-Z][A-Z0-9_]*$/.test(name)) throw new Error(`${name} cannot be a Rust constant`);
		if (!Number.isSafeInteger(value) || value < 0) throw new Error(`${name} is not a count`);
		return `pub const ${name}: usize = ${value};\n`;
	});
	return `${RUST_GENERATED_HEADER}\n${declarations.join("")}`;
}

function modFile(modules: readonly string[]): string {
	const declarations = modules.map((module) => `mod ${module};\n`).join("");
	const exports = modules.map((module) => `pub use ${module}::*;\n`).join("");
	return `${RUST_GENERATED_HEADER}\n${declarations}\n${exports}`;
}

function moduleFile(moduleTypes: readonly TypeDef[], fields: RustFields): string {
	const declared = new Set(moduleTypes.map((type) => type.name));
	// rustfmt orders `super` before any crate.
	const imports = [
		...(referencesOf(moduleTypes, fields).some((name) => !declared.has(name)) ? ["use super::*;\n"] : []),
		...(moduleTypes.some((type) => type.kind !== "alias") ? ["use serde::{Deserialize, Serialize};\n"] : []),
	];
	const declarations = moduleTypes.map((type) => declaration(type, fields)).join("\n");
	const head = imports.length > 0 ? `${imports.join("")}\n` : "";
	return `${RUST_GENERATED_HEADER}\n${head}${declarations}`;
}

function referencesOf(moduleTypes: readonly TypeDef[], fields: RustFields): string[] {
	return moduleTypes.flatMap((type) => {
		switch (type.kind) {
			case "class":
				return type.fields.flatMap((field) => fields.references(field.type));
			case "union":
				return type.members;
			case "alias":
				return fields.references(type.target);
			default:
				return [];
		}
	});
}

function declaration(type: TypeDef, fields: RustFields): string {
	switch (type.kind) {
		case "class":
			return structDeclaration(type, fields);
		case "union":
			return unionDeclaration(type, fields);
		case "enum":
			return enumDeclaration(type, fields);
		case "alias":
			return `pub type ${fields.name(type.name)} = ${fields.aliasTarget(type.name, type.target)};\n`;
		case "json":
			throw new Error(`${type.name} is written by hand`);
	}
}

function structDeclaration(type: ClassDef, fields: RustFields): string {
	const name = fields.name(type.name);
	const lines = type.fields.flatMap((field) => fields.declaration(type.name, field)).map((line) => INDENT + line);
	const body = lines.length === 0 ? `pub struct ${name} {}\n` : `pub struct ${name} {\n${lines.join("\n")}\n}\n`;
	const attributes = [...RECORD_DERIVES, '#[serde(rename_all = "camelCase", deny_unknown_fields)]'];
	return `${attributes.join("\n")}\n${body}${taggedImpl(type, name)}`;
}

/** A union member knows its tag, so it can carry the tag when it stands alone (`crate::tagged`). */
function taggedImpl(type: ClassDef, name: string): string {
	const keys = Object.keys(type.tags);
	if (keys.length > 1) {
		throw new Error(`${type.name}: tagged by ${keys.join(" and ")}; serde reads exactly one discriminator`);
	}
	const [key] = keys;
	if (key === undefined) return "";
	return (
		`\nimpl crate::Tagged for ${name} {\n` +
		`${INDENT}const KEY: &'static str = ${rustString(key)};\n` +
		`${INDENT}const TAG: &'static str = ${rustString(tagValue(type, key))};\n}\n`
	);
}

function unionDeclaration(type: UnionDef, fields: RustFields): string {
	const variants = type.members.map((member) => {
		const wire = tagValue(memberOf(type, member, fields), type.key);
		return { wire, name: rustVariantName(type.name, wire), payload: `(${fields.name(member)})` };
	});
	const attributes = [...UNION_DERIVES, `#[serde(tag = ${rustString(type.key)})]`];
	return `${attributes.join("\n")}\n${enumBody(type.name, fields.name(type.name), variants)}`;
}

/** A member tagged twice is refused where its struct is written (`taggedImpl`). */
function memberOf(union: UnionDef, member: string, fields: RustFields): ClassDef {
	const type = fields.lookup(member);
	if (type.kind !== "class") throw new Error(`${union.name}: member ${member} is not a class`);
	return type;
}

function enumDeclaration(type: EnumDef, fields: RustFields): string {
	const variants = type.values.map((wire) => ({ wire, name: rustVariantName(type.name, wire), payload: "" }));
	return `${ENUM_DERIVES.join("\n")}\n${enumBody(type.name, fields.name(type.name), variants)}`;
}

function enumBody(owner: string, name: string, variants: { wire: string; name: string; payload: string }[]): string {
	const seen = new Map<string, string>();
	for (const variant of variants) {
		const other = seen.get(variant.name);
		if (other !== undefined) throw new Error(`${owner}: "${other}" and "${variant.wire}" are both ${variant.name}`);
		seen.set(variant.name, variant.wire);
	}
	const lines = variants.map(
		(variant) =>
			`${INDENT}#[serde(rename = ${rustString(variant.wire)})]\n${INDENT}${variant.name}${variant.payload},\n`,
	);
	return `pub enum ${name} {\n${lines.join("")}}\n`;
}
